using System.IO;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using HyperLib.Core;
using Hypershell.Models;
using Hypershell.Services;

public static class StudioNavigationVerifier
{
    public static async Task<string> RunAsync(string output,string sourceLibraryRoot,CancellationToken ct=default)
    {
        Directory.CreateDirectory(output);var checks=new List<string>();void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);checks.Add(message);}
        var presets=HyperlibNavigationLayouts.All.Select(preset=>{var layout=HyperlibNavigationLayouts.Create(preset.Id);HyperlibHeaderLayouts.Validate(layout);var node=JsonSerializer.SerializeToNode(layout,ContentJson.Options)!;RemoveIds(node);return node.ToJsonString(ContentJson.Options);}).ToArray();
        Check(presets.Length==6&&presets.Distinct(StringComparer.Ordinal).Count()==6,"Six Navigation foundations provide distinct editable Blocks rather than image-only presets.");
        foreach(var preset in HyperlibNavigationLayouts.All)Check(HyperlibHeaderLayouts.Elements(HyperlibNavigationLayouts.Create(preset.Id)).Any(element=>element.Kind=="navigation"&&element.Navigation?.AutoPages==true),preset.Title+" includes functional editable Work links.");
        foreach(var target in new[]{"javascript:alert(1)","data:text/html,bad","//untrusted.example","/%2fexample.com","/%5cbad","/a/%2e%2e/b","","#","page:","mailto:","mailto:?subject=Hello","tel:","http:\\bad"})Check(!HyperlibNavigationLayouts.IsSafeTarget(target),"Reject unsafe or incomplete custom target: "+target);
        Check(HyperlibNavigationLayouts.IsSafeTarget("mailto:editor@example.com")&&HyperlibNavigationLayouts.IsSafeTarget("tel:+15555550123")&&HyperlibNavigationLayouts.IsSafeTarget("https://example.com/guide"),"Email, phone, and normal HTTPS navigation targets remain supported.");
        Check(HyperlibNavigationLayouts.ResolveTarget("page:chapter-one")=="page/chapter-one"&&HyperlibNavigationLayouts.ResolveTarget("/page/chapter-one")=="page/chapter-one"&&HyperlibNavigationLayouts.ResolveTarget("#details")=="#details", "Page references and genuine anchors resolve to meaningful portable URLs.");
        var generator=new HyperlibWorkProjectService(sourceLibraryRoot);var textChoice=generator.GetCatalog().First(item=>item.GroupId=="blank"&&item.ComponentName=="TextBlock"&&item.Kind=="element");
        var navigation=HyperlibNavigationLayouts.Create("brand-and-links");var links=HyperlibHeaderLayouts.Elements(navigation).Single(element=>element.Kind=="navigation");
        links.Navigation!.CustomLinks.Add(new(){Id="custom-reference",Label="Reference Page",Target="page:nav-reference-page"});links.Navigation.ShowPreviousNext=true;
        var imagePath=Path.Combine(output,"navigation-logo.svg");await File.WriteAllTextAsync(imagePath,"<svg xmlns='http://www.w3.org/2000/svg' width='80' height='60'><rect width='80' height='60' fill='#65a88e'/></svg>",ct);
        var media=new HyperlibHeaderElementDefinition{Kind="image",WidthMode="pixels",WidthPixels=48,Height=48,MediaPath=imagePath};navigation.Blocks[0].Elements.Insert(0,media);
        var recipe=new HyperlibPageTemplateDefinition{HeaderLayout=HyperlibHeaderLayouts.Create("simple-title"),NavigationLayout=navigation,NavigationSticky=true,NavigationPlacement="top",BodyTemplateId=textChoice.Id};
        var alternate=new HyperlibNamedPageTemplateDefinition{Id="plain-page",Name="Plain Page",Definition=new(){IncludeNavigation=false}};
        var project=await generator.CreateAsync(Path.Combine(output,"navigation-project-"+Guid.NewGuid().ToString("N")),"site",new(){PipelineVersion=2,WorkTitle="Navigation verification",SelectedToolsetIds=[textChoice.Id],LandingTemplate=ContentJson.Clone(recipe),PageTemplate=recipe,PageTemplates=[new(){Id="page-default",Name="Navigation Page",Definition=recipe},alternate]},ct);
        var library=Path.GetFullPath(Path.Combine(project,"../.."));var service=new HyperlibProjectPipelineService();var pipeline=(await service.ReadAsync(project,ct))!;var template=TemplateObjectLibrary.ReadDefinition(project);
        Check(template.Regions.Any(region=>region.Id=="navigation")&&pipeline.PageTemplate.Blocks.Count(block=>block.Type==HyperlibNavigationLayouts.LayoutBlockType)==1&&!pipeline.PageTemplate.Blocks.Any(block=>block.Type=="studio-navigation"),"The composed Navigation occupies its dedicated full-Page region without duplicate legacy navigation.");
        Check(pipeline.PageTemplate.Appearance["studioNavigationBuilder"].GetBoolean()&&pipeline.PageTemplate.Appearance["studioNavigationCss"].GetString()=="", "Navigation Blocks own their visual styling without old region-padding duplication.");
        var ownedMedia=HyperlibHeaderLayouts.Elements(pipeline.PageTemplate.Definition.NavigationLayout).Single(element=>element.Id==media.Id).MediaPath;
        Check(ownedMedia.StartsWith("/media/studio-header/",StringComparison.Ordinal)&&File.Exists(Path.Combine(library,"Media",ownedMedia[7..])),"Navigation media is copied into the independently owned project.");
        var store=new ContentStore(library);var state=await store.ReadAsync(ct);var landing=ContentJson.Clone(state.Pages[pipeline.LandingPageId]);var original=ContentJson.Clone(landing);
        foreach(var preset in HyperlibNavigationLayouts.All){var composed=HyperlibProjectPipelineService.Compose(new(){NavigationLayout=HyperlibNavigationLayouts.Create(preset.Id)},pipeline.Toolkit,template,"preset");landing.Revision=state.Pages[landing.Id].Revision;landing.Blocks=composed.Blocks;
            state=await store.ApplyAsync(new(){ExpectedRevision=state.Revision,Description="Persist real Navigation foundation "+preset.Title,Operations=[new(){Kind="savePage",Page=landing}]},ct);Check(state.Pages[landing.Id].Blocks.Any(block=>block.Type==HyperlibNavigationLayouts.LayoutBlockType),"Actual content validation, journal, and readback accept "+preset.Title+".");}
        original.Revision=state.Pages[original.Id].Revision;var body=original.Blocks.Single(block=>block.Type==pipeline.Toolkit.Single(item=>item.ChoiceId==textChoice.Id).BlockTypeIds[0]);body.Values["text"]=ContentJson.Value(string.Join("\n\n",Enumerable.Range(1,100).Select(number=>"Scrollable Page body paragraph "+number+". Navigation should remain visible while reading.")));
        state=await store.ApplyAsync(new(){ExpectedRevision=state.Revision,Description="Restore navigation fixture and long authored body",Operations=[new(){Kind="savePage",Page=original}]},ct);
        using var hosts=new HyperlibWorkPreviewHostService();var endpoint=await hosts.EnsureAsync(library,ct);using var client=new HttpClient{Timeout=TimeSpan.FromMinutes(3)};client.DefaultRequestHeaders.Add("X-HyperLib-Client","editor");
        state=await Post(client,endpoint,new(){ExpectedRevision=state.Revision,Description="Create actual Pages for dynamic navigation",Operations=[new(){Kind="createNode",Id="nav-reference-page",NodeType="page",ParentId=pipeline.WorkId,Title="Reference Page"},new(){Kind="createNode",Id="nav-first-page",NodeType="page",ParentId=pipeline.WorkId,Title="First dynamic Page"},new(){Kind="createNode",Id="nav-other-page",NodeType="page",ParentId=pipeline.WorkId,Title="Other template",Appearance=new(){["studioPageTemplateId"]=ContentJson.Value(alternate.Id)}}]},ct);
        var other=JsonSerializer.Serialize(state.Pages["nav-other-page"],ContentJson.Options);
        var html=await Html(client,endpoint,pipeline.WorkId,pipeline.LandingPageId,ct);
        Check(html.Contains("page/nav-first-page",StringComparison.Ordinal)&&html.Contains("First dynamic Page",StringComparison.Ordinal)&&html.Contains("Reference Page",StringComparison.Ordinal)&&html.Contains("studio-navigation-links",StringComparison.Ordinal),"The compiled Work renders real dynamic Page links and configured custom link labels.");
        state=await Post(client,endpoint,new(){ExpectedRevision=state.Revision,Description="Add a Page after Navigation was staged",Operations=[new(){Kind="createNode",Id="nav-later-page",NodeType="page",ParentId=pipeline.WorkId,Title="Later dynamic Page"}]},ct);
        html=await Html(client,endpoint,pipeline.WorkId,pipeline.LandingPageId,ct);Check(html.Contains("page/nav-later-page",StringComparison.Ordinal)&&html.Contains("Later dynamic Page",StringComparison.Ordinal),"Automatic Navigation includes later Pages without restaging the template.");
        var authored=ContentJson.Clone(state.Pages["nav-first-page"]);var navBlock=authored.Blocks.Single(block=>block.Type==HyperlibNavigationLayouts.LayoutBlockType);var live=JsonSerializer.Deserialize<HyperlibHeaderLayoutDefinition>(navBlock.Values["layout"].GetString()!,ContentJson.Options)!;
        HyperlibHeaderLayouts.Elements(live).Single(element=>element.Id==links.Id).Navigation!.CustomLinks[0].Label="Independently authored link";
        navBlock.Values["layout"]=ContentJson.Value(JsonSerializer.Serialize(live,ContentJson.Options));authored.Sources.Add(new(){Id="nav-source",Title="Navigation source",Url="https://example.com",RetrievedAt=DateTimeOffset.UtcNow,BlockIds=[navBlock.Id]});
        state=await store.ApplyAsync(new(){ExpectedRevision=state.Revision,Description="Author one custom Navigation link",Operations=[new(){Kind="savePage",Page=authored}]},ct);
        var next=(await service.ReadDefinitionAsync(project,ct))!;var shared=HyperlibHeaderLayouts.Elements(next.PageTemplate.NavigationLayout).Single(element=>element.Id==links.Id).Navigation!;shared.CustomLinks[0].Label="Updated shared label";shared.CustomLinks[0].Target="page:nav-later-page";shared.Gap=22;
        pipeline=await generator.UpdateFoundationAsync(project,next,pipeline.Revision,state.Revision,ct);state=await store.ReadAsync(ct);
        var merged=JsonSerializer.Deserialize<HyperlibHeaderLayoutDefinition>(state.Pages[authored.Id].Blocks.Single(block=>block.Id==navBlock.Id).Values["layout"].GetString()!,ContentJson.Options)!;var settings=HyperlibHeaderLayouts.Elements(merged).Single(element=>element.Id==links.Id).Navigation!;
        Check(settings.CustomLinks[0].Label=="Independently authored link"&&settings.CustomLinks[0].Target=="page:nav-later-page"&&settings.Gap==22,"Template updates preserve an authored link label while untouched targets and spacing follow the new foundation.");
        Check(JsonSerializer.Serialize(state.Pages["nav-other-page"],ContentJson.Options)==other&&state.Pages[authored.Id].Sources.Single().BlockIds.Contains(navBlock.Id),"Navigation updates preserve citations and isolate Pages assigned to another template.");
        Check(pipeline.PageTemplate.Appearance.All(item=>item.Value.GetRawText().Length<=4096)&&File.ReadAllText(Path.Combine(project,"src/Pages/wwwroot/work-theme.css")).Contains("studio-navigation-layouts-v1",StringComparison.Ordinal),"Navigation source/styles are portable and preserve existing appearance field limits.");
        var refreshed=await hosts.EnsureAsync(library,ct);using(var runtime=JsonDocument.Parse(await client.GetStringAsync(new Uri(refreshed,"api/runtime/"+pipeline.WorkId),ct))){var prefix=runtime.RootElement.GetProperty("proxyPrefix").GetString()!;var url=new Uri(refreshed,prefix.TrimStart('/')+"page/"+pipeline.LandingPageId);await File.WriteAllTextAsync(Path.Combine(output,"navigation-browser.json"),JsonSerializer.Serialize(new{url=url.AbsoluteUri,project,sourceLibraryRoot,workId=pipeline.WorkId,stateUrl=new Uri(refreshed,"api/state").AbsoluteUri,operationsUrl=new Uri(refreshed,"api/operations").AbsoluteUri},ContentJson.Options),ct);
            var script=Path.Combine(AppContext.BaseDirectory,"verify-studio-navigation.cjs");if(!File.Exists(script))script=Path.GetFullPath(Path.Combine(Environment.CurrentDirectory,"tools/verify-studio-navigation.cjs"));if(!File.Exists(script))throw new FileNotFoundException("Copy the actual Navigation browser verifier beside the verifier executable.",script);
            var run=await new BoundedProcessRunner().RunAsync(new(){ExecutablePath="C:/Users/ihigg/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node.exe",Arguments=[script,Path.Combine(output,"navigation-browser.json"),output],WorkingDirectory=output,Timeout=TimeSpan.FromSeconds(90),MaximumStandardOutputCharacters=20000,MaximumStandardErrorCharacters=20000},ct);Check(run.ExitCode==0,"Actual browser links, sticky scrolling, active styles, and responsive Menu passed: "+run.StandardOutput+run.StandardError);}
        var result="STUDIO_NAVIGATION_OK|checks="+checks.Count;await File.WriteAllTextAsync(Path.Combine(output,"studio-navigation-result.json"),JsonSerializer.Serialize(new{result,checks,project},ContentJson.Options),ct);return result;
    }
    public static async Task<string> VerifyUpgradeAsync(string output,string oldWorkRoot,string sourceLibraryRoot,CancellationToken ct=default)
    {
        Directory.CreateDirectory(output);var original=Path.GetFullPath(Path.Combine(oldWorkRoot,"../.."));var hashes=StudioGuidedUpgradeVerifier.HashTree(original);var library=Path.Combine(Path.GetFullPath(output),"old-drag-copy-"+Guid.NewGuid().ToString("N"));if(!library.Contains("qa",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use isolated QA output.");
        await StudioGuidedUpgradeVerifier.CopyTreeAsync(original,library,ct);var project=Path.Combine(library,Path.GetRelativePath(original,oldWorkRoot));var service=new HyperlibProjectPipelineService();var pipeline=(await service.ReadAsync(project,ct))!;var store=new ContentStore(library);var before=await store.ReadAsync(ct);
        var definition=(await service.ReadDefinitionAsync(project,ct))!;definition.LandingTemplate.NavigationLayout=HyperlibNavigationLayouts.Create("simple-links");definition.PageTemplate.NavigationLayout=HyperlibNavigationLayouts.Create("two-level");definition.PageTemplate.NavigationSticky=true;
        // This actual Header fixture deliberately disabled Navigation. Simulate choosing a Navigation
        // foundation in the wizard, whose change handler also enables its region and placement.
        definition.LandingTemplate.IncludeNavigation=true;definition.LandingTemplate.NavigationPlacement="top";definition.PageTemplate.IncludeNavigation=true;definition.PageTemplate.NavigationPlacement="top";
        pipeline=await new HyperlibWorkProjectService(sourceLibraryRoot).UpdateFoundationAsync(project,definition,pipeline.Revision,before.Revision,ct);var after=await store.ReadAsync(ct);
        Require(before.Pages.All(pair=>after.Pages.ContainsKey(pair.Key)&&pair.Value.Blocks.Where(block=>block.Type!="studio-navigation").All(block=>after.Pages[pair.Key].Blocks.Any(current=>current.Id==block.Id))&&JsonSerializer.Serialize(pair.Value.Sources,ContentJson.Options)==JsonSerializer.Serialize(after.Pages[pair.Key].Sources,ContentJson.Options)),"Navigation upgrade preserves authored old objects and citations while replacing untouched legacy Navigation.");
        Require(TemplateObjectLibrary.ReadDefinition(project).Regions.Any(region=>region.Id=="navigation"),"An enabled Navigation foundation upgrades the Work with its dedicated fifth region.");
        Require(File.Exists(Path.Combine(project,"src/Pages/Blocks/StudioNavigationLinksBlock.razor")),"Upgrade installs the actual functional Navigation component.");
        Require(Directory.Exists(Path.Combine(library,".studio/upgrades")),"Upgrade keeps prior generated source in its private backup directory.");
        var final=StudioGuidedUpgradeVerifier.HashTree(original);Require(final.Count==hashes.Count&&hashes.All(pair=>final.GetValueOrDefault(pair.Key)==pair.Value),"The deployed source fixture remains unchanged.");var result="STUDIO_NAVIGATION_UPGRADE_OK|checks=5";await File.WriteAllTextAsync(Path.Combine(output,"studio-navigation-upgrade-result.txt"),result+"\n"+project,ct);return result;
    }
    private static async Task<string> Html(HttpClient client,Uri endpoint,string work,string page,CancellationToken ct){using var runtime=JsonDocument.Parse(await client.GetStringAsync(new Uri(endpoint,"api/runtime/"+work),ct));return await client.GetStringAsync(new Uri(endpoint,runtime.RootElement.GetProperty("proxyPrefix").GetString()!.TrimStart('/')+"page/"+page),ct);}
    private static async Task<LibraryState> Post(HttpClient client,Uri endpoint,OperationBatch batch,CancellationToken ct){using var response=await client.PostAsync(new Uri(endpoint,"api/operations"),new StringContent(JsonSerializer.Serialize(batch,ContentJson.Options),Encoding.UTF8,"application/json"),ct);var raw=await response.Content.ReadAsStringAsync(ct);Require(response.IsSuccessStatusCode,raw);return JsonSerializer.Deserialize<LibraryState>(raw,ContentJson.Options)!;}
    private static void RemoveIds(JsonNode node){if(node is JsonObject obj){obj.Remove("id");foreach(var item in obj.ToArray())if(item.Value is not null)RemoveIds(item.Value);}else if(node is JsonArray arr)foreach(var item in arr)if(item is not null)RemoveIds(item);}
    private static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
}
